(() => {
 const data=window.TERRA_RACES;
 const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const region=id=>window.TERRA?.regions.find(r=>r.id===id);
 const state={id:null,prefs:{full:false},q:'',region:'all',shown:24};
 const recordsFor=entry=>{
  const matches=new Map();
  for(const p of window.ROSTER_RENDER?.all||[]){
   if(p.kind!=='operator')continue;
   const record=window.PROFILE_UI?.get(p.id);
   const races=[...new Set((record?.options||[]).map(o=>o.basic.find(x=>x.label==='种族')?.value).filter(value=>entry.profileNames.includes(value)))];
   if(!races.length)continue;
   const identity=window.PERSON_BIOGRAPHIES?.recordToPerson[p.id]||p.id;
   if(matches.has(identity)){const old=matches.get(identity);old.races=[...new Set([...old.races,...races])];}
   else matches.set(identity,{p:window.ROSTER_RENDER.index.get(identity)||p,races});
  }
  return [...matches.values()].sort((a,b)=>a.p.name.localeCompare(b.p.name,'zh-CN'));
 };
 const cached=new Map();
 const people=entry=>{if(!cached.has(entry.id))cached.set(entry.id,recordsFor(entry));return cached.get(entry.id);};
 const paragraphs=body=>body.split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('');
 const refs=rows=>rows.map(r=>`<a href="${esc(r.url)}">${esc(r.label)} ↗</a>`).join('；');
 const regionLinks=entry=>entry.relatedRegions.map(id=>{const r=region(id);return r?`<a href="#/atlas/${esc(id)}">${esc(r.name)} ↗</a>`:'';}).join('');
 const matches=(entry,q)=>[entry.name,entry.en,entry.summary,entry.profileNames.join(' '),...entry.relatedRegions.map(id=>region(id)?.name||''),...(state.prefs.full?entry.sections.map(s=>s.title+' '+s.body):[])].join(' ').toLocaleLowerCase().includes(q.toLocaleLowerCase());
 function card(entry){return `<a class="race-card" href="#/races/${entry.id}"><div class="race-card-meta"><span>${esc(entry.en)}</span><span>${String(data.entries.indexOf(entry)+1).padStart(2,'0')}</span></div><h2>${esc(entry.name)}</h2><p>${esc(entry.summary)}</p><div class="race-card-bottom"><span>${entry.relatedRegions.map(id=>region(id)?.name).filter(Boolean).map(esc).join(' · ')}</span><strong>阅读专题 ↗</strong></div></a>`;}
 function catalogue(){return `<div class="wrap races-wrap"><header class="page-heading"><div><div class="eyebrow">PEOPLES & HISTORIES OF TERRA</div><h1>种族专题</h1><p>从族群来源、迁徙与社会生活读起，再与各地历史和人物经历相互对照。</p></div><div class="page-mark" aria-hidden="true">族</div></header><div class="races-intro"><div><span class="eyebrow">TERRA: A JOURNEY · CHAPTER IV</span><h2>共同生活之中，各有来处</h2><p>依据《大地巡旅》第四章的 ${data.meta.entries} 个具名种族主条目原创整理。形貌之外，家族、职业、地方制度与历史选择，也构成一个人的身份。</p></div><div class="races-intro-count"><strong>${data.meta.entries}</strong><span>篇种族主条目</span><a href="#/sources/reference/journey-races">校读范围与出处 ↗</a></div></div><details class="races-guide"><summary>阅读前：先民、神民、兽亲与族群名称</summary><div class="races-guide-grid">${data.overview.map(s=>`<section><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p></section>`).join('')}</div><p class="races-note">${esc(data.meta.scope)} ${esc(data.meta.sourceKind)}。${esc(data.meta.method)}</p></details><div class="toolbar races-toolbar"><label class="search-inline"><input id="race-query" type="search" value="${esc(state.q)}" placeholder="搜索种族、文化或关联地区…" aria-label="搜索种族专题"></label><select id="race-region" aria-label="按关联地区筛选种族专题"><option value="all">全部关联地区</option>${window.TERRA.regions.filter(r=>data.entries.some(e=>e.relatedRegions.includes(r.id))).map(r=>`<option value="${r.id}" ${state.region===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select><span id="race-result-count" class="result-count" role="status" aria-live="polite"></span></div><div class="low-spoiler-banner"><span>${state.prefs.full?'完整阅读已开启，可搜索历史与文化正文。':'低剧透导览：可搜索名称、概要与关联地区，详情中的历史正文需开启完整阅读。'}</span><button data-action="toggle-full">${state.prefs.full?'切换低剧透':'开启完整阅读'}</button></div><div class="race-grid" id="race-results"></div><p class="races-note">人物关联依据游戏基础档案的公开种族字段建立，异格按官方关联归并。未公开或不明的字段保持原登记，不按外貌推定。专题中的群体描述不代替个人年龄、体检与源石技艺档案。</p></div>`;}
 function draw(){const target=document.getElementById('race-results');if(!target)return;const list=data.entries.filter(entry=>(state.region==='all'||entry.relatedRegions.includes(state.region))&&(!state.q.trim()||matches(entry,state.q.trim())));target.innerHTML=list.length?list.map(card).join(''):'<div class="empty"><h2>没有找到相应条目</h2><p>可以换一个种族名、地区名，或清除筛选条件。</p><button data-race-reset>重置筛选</button></div>';document.getElementById('race-result-count').textContent=`${list.length} / ${data.meta.entries} 篇`;}
 function peopleGrid(entry){const list=people(entry),shown=list.slice(0,state.shown);return `${list.length?`<div class="race-people-grid">${shown.map(({p,races})=>`<a class="race-person" href="#/character/${p.id}">${window.ART_UI?.thumb(p)||''}<div><h3>${esc(p.name)} ↗</h3><p>档案登记：${races.map(esc).join(' / ')}</p><small>${esc(region(p.region)?.name||'跨地区人物')}</small></div></a>`).join('')}</div>${shown.length<list.length?`<button class="race-more" data-race-more>继续显示人物（已显示 ${shown.length} / ${list.length}）</button>`:''}`:'<p class="races-note">当前人物名录未找到对应的公开种族字段。保留资料空缺，不用外貌推定或其他种族人物代替。</p>'}`;}
 function detail(entry){const list=people(entry);return `<div class="book-top"><div class="crumb"><a href="#/races">种族专题</a><span>/</span><span>${esc(entry.name)}</span></div><div class="reading-tools"><button data-action="toggle-full" class="${state.prefs.full?'selected':''}" aria-pressed="${!!state.prefs.full}">${state.prefs.full?'完整阅读 · 含剧透':'低剧透导览'}</button></div></div><div class="races-reading"><aside class="races-toc"><div class="eyebrow">IN THIS CHAPTER</div><a href="#race-start" data-anchor="race-start">篇首 · ${esc(entry.name)}</a>${state.prefs.full?entry.sections.map((s,i)=>`<a href="#race-section-${i}" data-anchor="race-section-${i}">${esc(s.title)}</a>`).join(''):''}<a href="#race-regions" data-anchor="race-regions">关联地区</a><a href="#race-people" data-anchor="race-people">相关人物</a><a href="#race-evidence" data-anchor="race-evidence">材料与编写范围</a><a href="#/races">返回种族目录 ↗</a></aside><article class="book race-book"><header class="book-head" id="race-start"><div class="eyebrow">PEOPLES OF TERRA · ${esc(entry.en)}</div><h1>${esc(entry.name)}纪事</h1><div class="book-subtitle">来源与迁徙 · 历史与文化 · 相关人物</div><div class="book-meta"><span>设定集原创转述</span><span>${entry.sections.length} 个叙述阶段</span><span>${list.length} 组公开档案人物</span></div></header><div class="book-intro">${esc(entry.summary)}</div>${state.prefs.full?`<div class="races-narrative">${entry.sections.map((s,i)=>`<section class="chapter-section race-section" id="race-section-${i}"><div class="period-label"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.period||'历史与生活')}</div><h2>${esc(s.title)}</h2>${paragraphs(s.body)}<div class="biography-evidence">材料：${refs(s.refs)}</div></section>`).join('')}</div>`:`<div class="spoiler-gate"><div class="eyebrow">BEFORE YOU CONTINUE</div><h2>阅读族群历史与文化</h2><p>完整正文包含古代历史、身份变化及部分世界观设定。概要和公开档案入口仍可在下方查阅。</p><button class="primary" data-action="toggle-full">开启完整阅读 →</button></div>`}<section class="race-related" id="race-regions"><div class="eyebrow">ACROSS THE LAND</div><h2>与地区纪事对照阅读</h2><p>这些地区有明确的历史、分布或文化联系，不表示族群仅限于这些国家，也不等同于人物国籍。</p><div class="race-region-links">${regionLinks(entry)}</div></section><section class="race-related" id="race-people"><div class="eyebrow">PEOPLE & PUBLIC DOSSIERS</div><h2>从族群走向个人</h2><p>${entry.id==='sarkaz'?'以下包括档案登记为萨卡兹，以及书中列为相关非王庭氏族的鬼、阿纳萨。每张卡片保留原始种族字段，不将这些称谓互相替换。':'依据游戏本体基础档案公开的种族字段关联人物；异格与常规形态合并为同一组。字段相同不代表相同出身、能力或人生经历。'}</p><div id="race-people-results">${peopleGrid(entry)}</div></section><section class="source-details race-evidence" id="race-evidence"><h2>材料与编写范围</h2><p>${esc(data.meta.sourceKind)}；本篇取第四章具名条目及相应批注，使用原创转述，未发布所提供的整份TXT。目录标示本章印刷页为 ${esc(data.meta.printedPages)}，不是按本地文本行数推算页码。</p><p>${refs(entry.sources)}</p><p>族群史和个人档案采用不同资料时点。传说、作者推论与具名见闻在正文中分别说明；未见明确记载的迁徙年份、寿命范围和技艺不作补写。<a href="#/sources/reference/journey-races">查看设定集校读说明 ↗</a></p></section><nav class="next-chapters"><a href="#/races"><small>← 种族目录</small><strong>继续阅读族群故事</strong></a><a href="#/people"><small>人物纪事 →</small><strong>走近具体的人</strong></a></nav></article></div>`;}
 function page(id,prefs={full:false}){state.id=id||null;state.prefs=prefs;state.shown=24;if(!id)return catalogue();const entry=data.entries.find(e=>e.id===id);return entry?detail(entry):'<div class="wrap section"><div class="empty"><h1>本卷尚未收录这一条目</h1><a href="#/races">返回种族专题 →</a></div></div>';}
 function activate(){if(!state.id)draw();}
 function search(q,prefs={full:false}){if(!q.trim())return '';const previous=state.prefs;state.prefs=prefs;const list=data.entries.filter(e=>matches(e,q.trim())).slice(0,8);state.prefs=previous;return list.length?`<div class="eyebrow" style="margin:23px 0 12px">种族专题 · 最多显示 8 条</div>${list.map(e=>`<a class="search-result" href="#/races/${e.id}" data-close-dialog="search-dialog"><small>种族历史 / ${esc(e.en)}</small><h3>${esc(e.name)}</h3><p>${esc(e.summary)}</p></a>`).join('')}`:'';}
 function forPerson(p){const raw=window.PROFILE_UI?.get(p.id);const values=(raw?.options||[]).map(o=>o.basic.find(x=>x.label==='种族')?.value);return data.entries.filter(e=>e.profileNames.some(name=>values.includes(name)));}
 function profileLink(p){const list=forPerson(p);return list.length?`<div class="race-profile-links"><span>种族专题</span>${list.map(e=>`<a href="#/races/${e.id}">${esc(e.name)} · 历史与文化 ↗</a>`).join('')}</div>`:'';}
 document.addEventListener('input',event=>{if(event.target.id!=='race-query')return;state.q=event.target.value;draw();});
 document.addEventListener('change',event=>{if(event.target.id!=='race-region')return;state.region=event.target.value;draw();});
 document.addEventListener('click',event=>{if(event.target.closest('[data-race-reset]')){state.q='';state.region='all';document.getElementById('race-query').value='';document.getElementById('race-region').value='all';draw();}if(event.target.closest('[data-race-more]')){const entry=data.entries.find(e=>e.id===state.id);if(!entry)return;state.shown+=24;document.getElementById('race-people-results').innerHTML=peopleGrid(entry);}});
 window.RACES_UI={page,activate,search,forPerson,profileLink,people};
})();
